//再帰関数
void dfs(int pos){
  //N個の部署について割り当てを決め終わったら、答えを更新する。
  if(pos==n){
    ans = min(ans,max(a,b));
    return;
  }
  //pos番目の部署をAに割り当てた場合
  a += k[pos];
  dfs(pos+1);
  a -= k[pos];
  //pos番目の部署をBに割り当てた場合
  b += k[pos];
  dfs(pos+1);
  b -= k[pos];
  return;
}

